window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[285]={"id":"285","numero":285,"titre":"Diarrhée chronique","objectifs":[{"id":"285-1","rang":"B","rubrique":"Diagnostic positif","titre":"Diarrhée chronique de l’enfant : connaître les principales hypothèses diagnostiques, les examens complémentaires pertinents","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":2},{"id":"285-2","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une maladie cœliaque","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"285-3","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes thérapeutiques de la prise en charge de la maladie cœliaque chez l’adulte et l’enfant","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"285-4","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une diarrhée chronique","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"285-5","rang":"A","rubrique":"Étiologies","titre":"Connaître les cinq principaux mécanismes de diarrhée chronique","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"285-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments d’interrogatoire et d’examen clinique permettant de s’orienter vers le mécanisme de la diarrhée","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":5},{"id":"285-7","rang":"B","rubrique":"Étiologies","titre":"Connaître les médicaments fréquemment responsables d’une diarrhée chronique","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"285-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens biologiques et morphologiques à réaliser systématiquement en première intention","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"285-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la stratégie d’exploration d’une diarrhée chronique","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":2},{"id":"285-10","rang":"A","rubrique":"Étiologies","titre":"Connaître les caractéristiques et les causes fréquentes d’une diarrhée motrice","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"285-11","rang":"A","rubrique":"Étiologies","titre":"Connaître les caractéristiques et les causes fréquentes d’une diarrhée osmotique","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"285-12","rang":"A","rubrique":"Étiologies","titre":"Connaître les caractéristiques et les causes fréquentes de malabsorption et de maldigestion","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"285-13","rang":"B","rubrique":"Épidémiologie","titre":"Connaître l’épidémiologie, les facteurs de risque et le terrain de la maladie cœliaque","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"285-14","rang":"A","rubrique":"Étiologies","titre":"Connaître les symptômes, et les signes cliniques et biologiques digestifs et extra-digestifs de la maladie cœliaque","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"285-15","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic positif de la maladie cœliaque","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":3},{"id":"285-16","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître l’association rare au déficit en IgA, source de faux négatif des sérologies","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"285-17","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la maladie cœliaque","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"285-18","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications de la maladie cœliaque et les éléments de surveillance","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"285-19","rang":"B","rubrique":"Étiologies","titre":"Connaître les caractéristiques cliniques et biologiques et les causes d’une diarrhée sécrétoire","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1}],"astuces":[],"liensGlobaux":[{"href":"https://www.cours-officiels-r2c-hge.fr","label":"cours-officiels-r2c-hge.fr"},{"href":"https://moodle.univ-lyon1.fr/course/view.php","label":"moodle.univ-lyon1.fr"},{"href":"https://radiopaedia.org/articles/coeliac-disease-3","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Diarrhée chronique confirmée (> 1 mois) — Orientation par l'aspect des selles, puis l'effet du jeûne, puis le trou osmotique","detail":"<h4>CAT — orientation mécanistique d'une <span class=\"kw-clinique\">diarrhée</span> chronique — Démarche diagnostique vers <span class=\"kw-clinique\">les</span> 5 mécanismes</h4>","branches":[{"to":"t-malabsorption","label":"Selles graisseuses / stéatorrhée (mastic, flottantes, tachant le papier)","color":"amber"},{"to":"t-exsudative","label":"Selles glairo-sanglantes / hémorragiques / dysentériques","color":"amber"},{"to":"q-jeune","label":"Selles hydriques / aqueuses « sans pus ni glaires »","color":"blue"}]},{"id":"t-malabsorption","kind":"terminal","label":"Diarrhée par malabsorption / maldigestion","color":"amber","detail":"<h4>Clinique</h4><ul><li>Selles <span class=\"kw-clinique\">abondantes</span>, jaunâtres ou grisâtres, <span class=\"kw-clinique\">graisseuses</span> (auréole huileuse), malodorantes, aspect « bouse de vache »</li><li><span class=\"kw-alerte\">Amaigrissement</span> quasi constant + syndrome carentiel (<span class=\"kw-clinique\">anémie</span>, <span class=\"kw-clinique\">ostéomalacie</span>, <span class=\"kw-alerte\">syndrome hémorragique</span> par carence en <span class=\"kw-bio\">vitamine K</span>)</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Stéatorrhée &gt; 7 g/24 h</span> ; <span class=\"kw-bio\">élastase fécale basse</span> (insuffisance pancréatique) ; <span class=\"kw-bio\">test au D-xylose</span></li><li><span class=\"kw-imagerie\">EOGD + biopsies de D2</span> → <span class=\"kw-alerte\">atrophie villositaire</span> (<span class=\"kw-etio\">maladie cœliaque</span>)</li></ul><h4>Causes</h4><ul><li><span class=\"kw-etio\">Maladie cœliaque</span> (principale), <span class=\"kw-etio\">maladie de Crohn</span>, <span class=\"kw-etio\">insuffisance pancréatique exocrine</span> (<span class=\"kw-clinique\">pancréatite chronique</span>, cancer du pancréas, mucoviscidose), <span class=\"kw-etio\">pullulation microbienne du grêle</span>, <span class=\"kw-etio\">maladie de Whipple</span>, <span class=\"kw-etio\">parasitoses</span></li></ul><h4>Renvoi</h4><ul><li>Item 281 (<span class=\"kw-clinique\">Pancréatite chronique</span>)</li></ul>"},{"id":"t-exsudative","kind":"terminal","label":"Diarrhée exsudative ou lésionnelle","color":"amber","detail":"<h4>Clinique</h4><ul><li>Selles <span class=\"kw-alerte\">glairo-sanglantes</span> si lésions recto-s<span class=\"kw-chiffre\">igm</span>oïdiennes ; exsudation parfois purement lymphatique</li><li><span class=\"kw-clinique\">Œdèmes des membres inférieurs</span> voire anasarque (fuite protéique) ; selon la cause : syndrome rectal, dysentérique, <span class=\"kw-clinique\">amaigrissement</span>, fièvre</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Clairance fécale de l'α-1-antitrypsine &gt; 20 mL/min</span> (confirme l'exsudation)</li><li><span class=\"kw-bio\">Hypoalbuminémie</span>, <span class=\"kw-bio\">hypocholestérolémie</span>, <span class=\"kw-bio\">lymphopénie</span>, <span class=\"kw-bio\">hypogammaglobulinémie</span> si exsudation majeure</li><li><span class=\"kw-imagerie\">Gastroscopie + iléocoloscopie</span> avec biopsies</li></ul><h4>Causes</h4><ul><li><span class=\"kw-alerte\">Rupture</span> de la barrière épithéliale : <span class=\"kw-etio\">Crohn</span>, <span class=\"kw-etio\">RCH</span>, tumeur ulcérée, <span class=\"kw-etio\">maladie de Ménétrier</span>, <span class=\"kw-etio\">maladie cœliaque</span></li><li>Obstacle lymphatique : <span class=\"kw-etio\">maladie de Waldmann</span>, <span class=\"kw-etio\">lymphome</span>, compression <span class=\"kw-etio\">tumorale</span></li><li>Hyperpression veineuse centrale : <span class=\"kw-etio\">péricardite constrictive</span>, <span class=\"kw-etio\">insuffisance cardiaque droite</span></li></ul>"},{"id":"q-jeune","kind":"decision","label":"Effet du jeûne sur la diarrhée ? — Épreuve de jeûne 48 h + ionogramme fécal (trou osmotique)","branches":[{"to":"t-secretoire","label":"Persiste au jeûne (trou osmotique fécal normal)","color":"red"},{"to":"q-osmotique","label":"Cède au jeûne","color":"green"}]},{"id":"t-secretoire","kind":"terminal","label":"Diarrhée sécrétoire","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Diarrhée</span> <span class=\"kw-clinique\">hydrique abondante</span> (<span class=\"kw-chiffre\">&gt; 500 mL/jour</span>), <strong>diurne et nocturne</strong>, impérieuse</li></ul><h4>Élément discriminant</h4><ul><li><span class=\"kw-alerte\">Ne régresse pas (complètement) au jeûne</span> ; <span class=\"kw-bio\">trou osmotique fécal normal</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Hypokaliémie</span>, <span class=\"kw-bio\">acidose métabolique</span>, <span class=\"kw-bio\">insuffisance rénale fonctionnelle</span></li><li><span class=\"kw-imagerie\">Coloscopie</span> indispensable + biopsies étagées ; dosages hormonaux</li></ul><h4>Causes</h4><ul><li><span class=\"kw-etio\">Colites</span> (<span class=\"kw-clinique\">MICI</span>, radique, médicamenteuse) et <span class=\"kw-etio\">colites microscopiques</span></li><li><span class=\"kw-etio\">Parasitoses</span> de l'immunodéprimé (Giardia, Cryptosporidium, Microsporidium, Isospora belli)</li><li><span class=\"kw-etio\">Tumeurs neuroendocrines</span> : Zollinger-Ellison (gastrine), VIPome ; <span class=\"kw-etio\">iatrogène</span> (<span class=\"kw-ttt\">colchicine</span>, laxatifs irritants)</li><li><span class=\"kw-etio\">Malabsorption primitive des acides biliaires</span> (soulagement rapide par <span class=\"kw-ttt\">cholestyramine</span>)</li></ul><h4>Renvoi</h4><ul><li>Item 282 (<span class=\"kw-clinique\">MICI</span>) · Item 301 (Tumeur côlon-rectum)</li></ul>"},{"id":"q-osmotique","kind":"decision","label":"Trou osmotique fécal et horaire des selles ? — Trou osmotique = 290 − 2 × (Na + K) ; volume et horaire","branches":[{"to":"t-osmotique","label":"Trou osmotique > 50 mOsm/kg (selles mousseuses, borborygmes, météorisme)","color":"blue"},{"to":"t-motrice","label":"Trou osmotique normal (faible volume, post-prandial/réveil, lientérie, rouge carmin < 6 h)","color":"green"}]},{"id":"t-osmotique","kind":"terminal","label":"Diarrhée osmotique","color":"blue","detail":"<h4>Clinique</h4><ul><li>Selles <span class=\"kw-clinique\">liquides, mousseuses</span> ; <span class=\"kw-clinique\">borborygmes</span>, <span class=\"kw-clinique\">flatulences</span>, <span class=\"kw-clinique\">météorisme abdominal</span> si soluté fermentescible ; pas d'<span class=\"kw-clinique\">AEG</span></li></ul><h4>Élément discriminant</h4><ul><li><span class=\"kw-clinique\">Cède au jeûne</span> ; <span class=\"kw-bio\">trou osmotique fécal &gt; 50 mOsm/kg</span></li></ul><h4>Causes</h4><ul><li><span class=\"kw-etio\">Lactose</span>, <span class=\"kw-etio\">FODMAPs et polyols</span> (xylitol, sorbitol, maltitol)</li><li><span class=\"kw-etio\">Magnésium</span>, <span class=\"kw-etio\">laxatifs osmotiques</span> (PEG, <span class=\"kw-ttt\">lactulose</span>), <span class=\"kw-etio\">antiacides</span></li><li><span class=\"kw-etio\">Déficit en lactase</span> (ou en saccharase-isomaltase, rare)</li></ul><h4>Confirmation</h4><ul><li><span class=\"kw-bio\">Test respiratoire au lactose</span> ou test d'exclusion (arrêt du lactose)</li></ul>"},{"id":"t-motrice","kind":"terminal","label":"Diarrhée motrice","color":"green","detail":"<h4>Clinique</h4><ul><li>Selles <span class=\"kw-clinique\">liquides de faible volume</span> (<span class=\"kw-chiffre\">&lt; 500 g/jour</span>), groupées en salves</li><li><span class=\"kw-clinique\">Impérieuses</span>, au <span class=\"kw-clinique\">réveil et en post-prandial</span>, rarement nocturnes ; <span class=\"kw-clinique\">lientérie</span> (débris alimentaires &lt;<span class=\"kw-chiffre\"> 8 h</span>)</li><li><span class=\"kw-clinique\">Cède au jeûne</span> ; pas de malabsorption ni d'<span class=\"kw-clinique\">AEG</span></li></ul><h4>Paraclinique</h4><ul><li>Test au <span class=\"kw-bio\">rouge carmin accéléré (&lt; 6 h)</span> ; <span class=\"kw-ttt\">ralentisseurs du transit</span> efficaces</li><li>Bilan d'orientation : <span class=\"kw-bio\">TSH</span>, <span class=\"kw-bio\">glycémie à jeun</span></li></ul><h4>Causes</h4><ul><li><span class=\"kw-etio\">Troubles fonctionnels intestinaux</span> (~<span class=\"kw-chiffre\">80 %</span>, diagnostic d'élimination)</li><li><span class=\"kw-etio\">Hyperthyroïdie</span>, <span class=\"kw-etio\">dysautonomie diabétique</span>, <span class=\"kw-etio\">alcool</span></li><li>Rares : <span class=\"kw-etio\">syndrome carcinoïde</span>, <span class=\"kw-etio\">cancer médullaire de la thyroïde</span>, <span class=\"kw-etio\">amylose</span></li></ul><h4>Renvoi</h4><ul><li>Item 242 (Hyperthyroïdie) · Item 284 (<span class=\"kw-clinique\">Syndrome de l</span>'intestin irritable)</li></ul>"}]},"cards":[{"i":"1a0e06b68bad","n":285,"o":"285-10","u":"Étiologies","t":"Connaître les caractéristiques et les causes fréquentes d’une diarrhée motrice","q":"Quelle est la caractéristique principale d'une diarrhée motrice chronique ?","a":"<p>La diarrhée motrice chronique se caractérise par une accélération du <strong>transit intestinal</strong>, sans réelle lésion pariétale organique ni malabsorption significative. Les selles sont souvent de <strong>petit volume</strong> et surviennent typiquement après les repas.</p>"},{"i":"2e256db0ea29","n":285,"o":"285-10","u":"Étiologies","t":"Connaître les caractéristiques et les causes fréquentes d’une diarrhée motrice","q":"Quelles sont les causes fréquentes de diarrhée motrice chronique ?","a":"<ul><li>Le <strong>syndrome de l'intestin irritable</strong> (SII) forme à prédominance diarrhéique, souvent déclenchée par le stress ou certains aliments.</li><li>Certaines <strong>neuropathies autonomes</strong> (ex: diabète).</li><li>Une <strong>hyperthyroïdie</strong>, qui accélère le transit général.</li><li>La consommation excessive de <strong>caféine</strong> ou de <strong>sorbitol</strong>.</li><li>Après une <strong>chirurgie digestive</strong>, notamment une vagotomie ou une cholécystectomie.</li></ul>"},{"i":"a45845f7f76f","n":285,"o":"285-10","u":"Étiologies","t":"Connaître les caractéristiques et les causes fréquentes d’une diarrhée motrice","q":"Quels sont les mécanismes physiopathologiques principaux d'une diarrhée motrice ?","a":"<p>Les mécanismes principaux sont une <strong>hyperkinésie intestinale</strong> ou une <strong>hypersensibilité viscérale</strong>. Cela peut être lié à une dysrégulation du système nerveux entérique, des facteurs humoraux ou des troubles de la motilité intestinale.</p>"},{"i":"57c803750408","n":285,"o":"285-12","u":"Étiologies","t":"Connaître les caractéristiques et les causes fréquentes de malabsorption et de maldigestion","q":"Quelles sont les causes fréquentes de maldigestion au niveau de l'intestin grêle ?","a":"<p>Les causes de maldigestion sont dues à un défaut de l'hydrolyse des nutriments au sein de la lumière intestinale. Les plus fréquentes sont :<ul><li><strong>Insuffisance pancréatique exocrine (IPE)</strong> : <ul><li><strong>Pancréatite chronique</strong> (la cause la plus fréquente d'IPE chez l'adulte)</li><li>Mucoviscidose</li><li>Cancer du pancréas (obstruction canalaire)</li><li>Résections pancréatiques</li></ul></li><li><strong>Syndrome de Zollinger-Ellison</strong> : L'hypersécrétion acide gastrique inactive les enzymes pancréatiques dans le duodénum.</li><li><strong>Déficit en sels biliaires</strong> : <ul><li>Cholestase chronique (cirrhose biliaire primitive, cholangite sclérosante primitive)</li><li>Sténose ou résection iléale (interruption du cycle entéro-hépatique des sels biliaires, comme dans l'iléite de Crohn).</li><li>Insuffisance hépatique sévère.</li></ul></li><li><strong>Pullulation bactérienne du grêle (SIBO)</strong> : Les bactéries déconjuguent les sels biliaires et consomment les nutriments.</li></ul>"},{"i":"9a151cda5eb8","n":285,"o":"285-12","u":"Étiologies","t":"Connaître les caractéristiques et les causes fréquentes de malabsorption et de maldigestion","q":"Quelles sont les causes fréquentes de malabsorption au niveau de l'intestin grêle ?","a":"<p>Les causes de malabsorption sont nombreuses et peuvent être classées selon leur mécanisme :<ul><li><strong>Causes muqueuses</strong> : <ul><li><strong>Maladie cœliaque</strong> (atrophie villositaire)</li><li>Maladie de Crohn</li><li>Entéropathie post-radique</li><li>Giardiase, cryptosporidiose</li><li>Ischémie intestinale chronique</li><li>Abêtalipoprotéinémie congénitale</li></ul></li><li><strong>Causes luminales</strong> (maldigestion) : <ul><li><strong>Insuffisance pancréatique exocrine</strong> (pancréatite chronique, mucoviscidose, cancer du pancréas)</li><li>Syndrome de Zollinger-Ellison (inactivation des enzymes pancréatiques par hyperacidité)</li><li><strong>Pullulation bactérienne du grêle (SIBO)</strong></li><li>Déficit en sels biliaires (insuffisance hépatique, cholestase chronique, résection iléale)</li></ul></li><li><strong>Causes post-muqueuses</strong> : <ul><li>Lymphangiectasie intestinale primitive ou secondaire (obstruction lymphatique)</li><li>Lymphome intestinal</li></ul></li></ul>"},{"i":"bdef91c5e6fe","n":285,"o":"285-12","u":"Étiologies","t":"Connaître les caractéristiques et les causes fréquentes de malabsorption et de maldigestion","q":"Quels sont les principaux signes cliniques évocateurs d'une malabsorption, notamment avec une stéatorrhée ?","a":"<p>Les principaux signes cliniques de malabsorption sont :<ul><li><strong>Diarrhée chronique</strong>, souvent de type graisseux (<strong>stéatorrhée</strong> : selles abondantes, pâles, luisantes, malodorantes, difficiles à chasser de la cuvette).</li><li><strong>Perte de poids</strong>, malgré un apport alimentaire conservé ou augmenté.</li><li><strong>Carences nutritionnelles multiples</strong>, traduisant l'étendue de la malabsorption : <ul><li>Anémie (fer, folates, B12)</li><li>Œdèmes (hypoalbuminémie)</li><li>Ostéomalacie / ostéoporose (vitamine D, calcium)</li><li>Troubles de la coagulation (vitamine K)</li><li>Dermite pellagroïde (vitamine B3)</li><li>Neuropathie périphérique (vitamine B12, B1)</li><li>Glossite, chéilite</li></ul></li><li>Météorisme, douleurs abdominales.</li></ul>"},{"i":"e4e6c0d3dbf3","n":285,"o":"285-12","u":"Étiologies","t":"Connaître les caractéristiques et les causes fréquentes de malabsorption et de maldigestion","q":"Comment définir et différencier les principaux mécanismes de la malabsorption du grêle ?","a":"<p>La <strong>malabsorption</strong> est l'incapacité de l'intestin grêle à absorber correctement un ou plusieurs nutriments issus de la digestion. Elle se différencie de la <strong>maldigestion</strong> qui est un problème d'hydrolyse des nutriments (ex: insuffisance pancréatique exocrine).</p><p>Les principaux mécanismes de la malabsorption sont :<ul><li><strong>Malabsorption pariétale</strong> : atteinte directe de l'entérocyte ou de la muqueuse (ex: maladie cœliaque, maladie de Crohn).</li><li><strong>Malabsorption luminale</strong> : déficit en sels biliaires, inactivation enzymatique (ex: insuffisance pancréatique, SIBO).</li><li><strong>Malabsorption post-muqueuse</strong> : atteinte du système lymphatique ou vasculaire empêchant le transport des nutriments absorbés (ex: lymphangiectasie intestinale).</li></ul>"},{"i":"04f2e2829cbf","n":285,"o":"285-14","u":"Étiologies","t":"Connaître les symptômes, et les signes cliniques et biologiques digestifs et extra-digestifs de la maladie cœliaque","q":"Quels sont les principaux symptômes digestifs de la maladie cœliaque chez l'adulte ?","a":"<p>Les symptômes digestifs de la maladie cœliaque chez l'adulte sont atypiques dans <strong>plus de 50% des cas</strong>. Ils peuvent inclure :</p><ul><li>Une <strong>diarrhée chronique</strong>.</li><li>Des <strong>douleurs abdominales</strong> diffuses.</li><li>Un <strong>ballonnement abdominal</strong>.</li><li>Une <strong>perte de poids</strong> inexpliquée.</li><li>Des <strong>nausées/vomissements</strong>.</li><li>Une <strong>constipation</strong> (plus rare).</li></ul>"},{"i":"1a71f157ee02","n":285,"o":"285-14","u":"Étiologies","t":"Connaître les symptômes, et les signes cliniques et biologiques digestifs et extra-digestifs de la maladie cœliaque","q":"Quels sont les signes biologiques clés à rechercher pour le diagnostic d'une maladie cœliaque ?","a":"<p>Les signes biologiques à rechercher pour le diagnostic d'une maladie cœliaque incluent :</p><ul><li><strong>Carence martiale</strong> (anémie ferriprive).</li><li><strong>Carence vitaminique</strong> (vitamine D, folates, B12).</li><li><strong>Hypocalcémie</strong>, <strong>hypophosphorémie</strong> et <strong>élévation de la PAL</strong> (en cas d'ostéomalacie).</li><li><strong>Hypercholestérolémie</strong> (paradoxalement liée à la malabsorption, baisse du LDL).</li><li><strong>Élévation des transaminases</strong>.</li><li><strong>Augmentation des anticorps anti-transglutaminase tissulaire</strong> (IgA, IgG si déficit en IgA) et des <strong>anticorps anti-endomysium</strong> (IgA).</li></ul>"},{"i":"6195d24df248","n":285,"o":"285-14","u":"Étiologies","t":"Connaître les symptômes, et les signes cliniques et biologiques digestifs et extra-digestifs de la maladie cœliaque","q":"Quels sont les principaux symptômes extra-digestifs de la maladie cœliaque chez l'adulte ?","a":"<p>La maladie cœliaque peut se manifester par de nombreux symptômes extra-digestifs chez l'adulte, souvent dominants :</p><ul><li><strong>Asthénie</strong>.</li><li><strong>Anémie ferriprive</strong> (la plus fréquente des <strong>carences</strong>).</li><li><strong>Ostéoporose</strong> ou <strong>ostéomalacie</strong>.</li><li><strong>Troubles neurologiques</strong> : neuropathie périphérique, ataxie, épilepsie.</li><li><strong>Troubles gynécologiques</strong> : aménorrhée, infertilité, avortements spontanés à répétition.</li><li><strong>Aphtes buccaux récurrents</strong>, <strong>hypoplasie de l'émail dentaire</strong>.</li><li><strong>Dermatite herpétiforme</strong> (lésions vésiculeuses prurigineuses symétriques).</li><li><strong>Hypertransaminasémie</strong> isolée.</li></ul>"},{"i":"7d0b5cb306cf","n":285,"o":"285-15","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic positif de la maladie cœliaque","q":"Actuellement, selon ma trame EDN, l'objectif \"Connaître les éléments du diagnostic positif de la maladie cœliaque\" est à compléter. Pourriez-vous me le fournir ?","a":"<p>Je ne peux pas générer les cartes de révision car le contenu lié à l'objectif \"Connaître les éléments du diagnostic positif de la maladie cœliaque\" est indiqué comme \"À compléter\". Veuillez me fournir le contenu pertinent.</p>"},{"i":"37a8f972702d","n":285,"o":"285-17","u":"Prise en charge","t":"Connaître les principes du traitement de la maladie cœliaque","q":"Quels sont les objectifs secondaires du traitement de la maladie cœliaque, au-delà du régime sans gluten ?","a":"<p>Les objectifs secondaires du traitement de la maladie cœliaque sont:</p><ul><li>La <strong>correction des carences nutritionnelles</strong> (fer, folates, vitamines, calcium, etc.) si elles sont présentes au diagnostic.</li><li>Le suivi régulier pour s'assurer de l'adhésion au régime et de la cicatrisation muqueuse.</li><li>La prise en charge des complications éventuelles, comme l'ostéoporose ou l'anémie.</li></ul>"},{"i":"693f72b1a365","n":285,"o":"285-17","u":"Prise en charge","t":"Connaître les principes du traitement de la maladie cœliaque","q":"Quelle est l'approche diététique nécessaire pour un patient atteint de maladie cœliaque ?","a":"<p>L'approche diététique implique la suppression de tous les aliments contenant:</p><ul><li>le <strong>blé</strong></li><li>l'<strong>orge</strong></li><li>le <strong>seigle</strong></li><li>(parfois l'avoine si contamination)</li></ul><p>Ceci nécessite une éducation thérapeutique et un suivi par un diététicien.</p>"},{"i":"e8d3bc7d971b","n":285,"o":"285-17","u":"Prise en charge","t":"Connaître les principes du traitement de la maladie cœliaque","q":"Quel est le principe fondamental du traitement de la maladie cœliaque ?","a":"<p>Le principe fondamental du traitement de la maladie cœliaque est l'<strong>exclusion stricte et à vie du gluten</strong> de l'alimentation.</p>"},{"i":"8cd778fc1961","n":285,"o":"285-3","u":"Prise en charge","t":"Connaître les principes thérapeutiques de la prise en charge de la maladie cœliaque chez l’adulte et l’enfant","q":"Quelle surveillance est recommandée après l'instauration d'un régime sans gluten pour la maladie cœliaque ?","a":"<p>La surveillance comprend :</p><ul><li>Une <strong>amélioration clinique</strong> des symptômes (diarrhée, douleurs abdominales, prise de poids chez l'enfant).</li><li>La normalisation des <strong>anticorps spécifiques</strong> (anti-transglutaminase, anti-endomysium) quelques mois après le début du régime.</li><li>Un suivi régulier par un gastro-entérologue pour évaluer l'observance, détecter d'éventuelles carences et surveiller les complications à long terme.</li></ul>"},{"i":"a82694feee50","n":285,"o":"285-3","u":"Prise en charge","t":"Connaître les principes thérapeutiques de la prise en charge de la maladie cœliaque chez l’adulte et l’enfant","q":"Quel est le traitement de la maladie cœliaque chez l'adulte et l'enfant ?","a":"<p>Le traitement de la maladie cœliaque, aussi bien chez l'adulte que chez l'enfant, repose exclusivement sur un <strong>régime sans gluten strict et à vie</strong>.</p>"},{"i":"c8e8c5d04ac8","n":285,"o":"285-3","u":"Prise en charge","t":"Connaître les principes thérapeutiques de la prise en charge de la maladie cœliaque chez l’adulte et l’enfant","q":"Quelles sont les implications du régime sans gluten dans la prise en charge de la maladie cœliaque ?","a":"<ul><li>Exclusion de tous les produits contenant du <strong>blé</strong>, de l'<strong>orge</strong> et du <strong>seigle</strong> (et parfois l'avoine selon les sensibilités individuelles et la pureté).</li><li>Nécessité d'une éducation thérapeutique pour le patient et sa famille.</li><li>Vigilance quant aux sources cachées de gluten (additifs, médicaments).</li><li>Consultation régulière avec un diététicien spécialisé.</li></ul>"},{"i":"1e96858a5d4a","n":285,"o":"285-4","u":"Définition","t":"Connaître la définition d’une diarrhée chronique","q":"Quelle est la définition d'une diarrhée, qu'elle soit aiguë ou chronique ?","a":"<p>Une diarrhée se définit par l'émission de <strong>selles trop fréquentes</strong> (généralement <strong>plus de 3 par jour</strong>) et/ou <strong>trop liquides</strong> (contenant plus de <strong>75% d'eau</strong>), et/ou en <strong>quantité trop importante</strong> (plus de <strong>300g par 24h</strong>).</p>"},{"i":"f33c9d4cf7c9","n":285,"o":"285-4","u":"Définition","t":"Connaître la définition d’une diarrhée chronique","q":"Comment distingue-t-on spécifiquement une diarrhée chronique d'une diarrhée aiguë ?","a":"<p>Une diarrhée est qualifiée de <strong>chronique</strong> lorsque ces symptômes persistent ou récidivent sur une période de <strong>plus de 4 semaines consécutives</strong>.</p>"},{"i":"2265ccd02801","n":285,"o":"285-5","u":"Étiologies","t":"Connaître les cinq principaux mécanismes de diarrhée chronique","q":"Comment caractériser la diarrhée chronique par malabsorption ?","a":"<p>La diarrhée chronique par malabsorption est due à une <strong>altération de l'absorption des nutriments</strong> (graisses, glucides, protéines) par l'intestin grêle. Elle se traduit souvent par une <strong>stéatorrhée</strong> (selles grasses, luisantes, qui flottent, malodorantes) et peut s'accompagner d'une <strong>perte de poids et de carences nutritionnelles</strong>.</p>"},{"i":"3db63b4b123a","n":285,"o":"285-5","u":"Étiologies","t":"Connaître les cinq principaux mécanismes de diarrhée chronique","q":"Quels sont les cinq principaux mécanismes physiopathologiques de la diarrhée chronique ?","a":"<p>Les cinq principaux mécanismes de la diarrhée chronique sont :</p><ul><li>La <strong>diarrhée motrice</strong></li><li>La <strong>diarrhée osmotique</strong></li><li>La <strong>diarrhée sécrétoire</strong></li><li>La <strong>diarrhée lésionnelle (ou exsudative)</strong></li><li>La <strong>malabsorption</strong></li></ul>"},{"i":"4b8a1da0c855","n":285,"o":"285-5","u":"Étiologies","t":"Connaître les cinq principaux mécanismes de diarrhée chronique","q":"Comment caractériser une diarrhée chronique sécrétoire ?","a":"<p>Une diarrhée chronique sécrétoire est due à une <strong>sécrétion intestinale excessive d'eau et d'électrolytes</strong>. Elle est généralement <strong>abondante</strong> (&gt; 1 litre/jour), <strong>ne cesse pas au jeun</strong> et le <strong>trou gap osmotique est bas</strong> (&lt; 50 mOsm/kg).</p>"},{"i":"7193c3b97bf9","n":285,"o":"285-5","u":"Étiologies","t":"Connaître les cinq principaux mécanismes de diarrhée chronique","q":"Comment caractériser une diarrhée chronique motrice ?","a":"<p>Une diarrhée chronique motrice est due à une <strong>accélération excessive du transit intestinal</strong>. Les selles sont souvent glaireuses, afécales ou peu abondantes, et surviennent typiquement après les repas.</p>"},{"i":"a78a9635c11f","n":285,"o":"285-5","u":"Étiologies","t":"Connaître les cinq principaux mécanismes de diarrhée chronique","q":"Comment caractériser une diarrhée chronique lésionnelle (ou exsudative) ?","a":"<p>Une diarrhée chronique lésionnelle est causée par une <strong>inflammation ou une ulcération de la muqueuse intestinale</strong>, entraînant une <strong>exsudation de sang, de pus, de protéines et de mucus</strong>. Les selles contiennent souvent du <strong>sang, du mucus, des leucocytes ou des protéines inflammatoires</strong> (calprotectine fécale).</p>"},{"i":"a857806925ed","n":285,"o":"285-5","u":"Étiologies","t":"Connaître les cinq principaux mécanismes de diarrhée chronique","q":"Comment caractériser une diarrhée chronique osmotique ?","a":"<p>Une diarrhée chronique osmotique est causée par la présence de <strong>substances osmotiquement actives non absorbées</strong> dans la lumière intestinale. Elle <strong>cesse généralement au jeun ou à l'arrêt de l'ingestion</strong> de la substance causale. Le <strong>trou gap osmotique est élevé</strong> (&gt; 125 mOsm/kg).</p>"},{"i":"1887c2954544","n":285,"o":"285-8","u":"Examens complémentaires","t":"Connaître les examens biologiques et morphologiques à réaliser systématiquement en première intention","q":"Quels sont les examens morphologiques systématiques de première intention à réaliser devant une diarrhée chronique ?","a":"<p>Devant une diarrhée chronique, les examens morphologiques systématiques de première intention sont :</p><ul><li><p><strong>Coloscopie avec iléoscopie et biopsies étagées</strong> : au minimum 2 biopsies dans l'iléon terminal, 2 biopsies dans le côlon droit, 2 biopsies dans le côlon transverse, 2 biopsies dans le côlon gauche et 2 biopsies dans le rectum.</p></li><li><p><strong>Endoscopie œso-gastro-duodénale (EOGD) avec biopsies duodénales</strong> : au minimum 4 biopsies du deuxième duodénum.</p></li></ul>"},{"i":"3bce5bc7c1ee","n":285,"o":"285-8","u":"Examens complémentaires","t":"Connaître les examens biologiques et morphologiques à réaliser systématiquement en première intention","q":"Quels sont les examens biologiques systématiques de première intention à réaliser devant une diarrhée chronique ?","a":"<p>Devant une diarrhée chronique, les examens biologiques systématiques de première intention sont :</p><ul><li>Bilan martial (NFS, ferritinémie, coefficient de saturation de la transferrine)</li><li>Électrolytes sanguins (ionogramme sanguin), fonction rénale (créatininémie), glycémie</li><li>Bilan hépatique (transaminases, phosphatases alcalines, gamma-GT, bilirubine)</li><li>Bilan inflammatoire (CRP, VS)</li><li>Électrophorèse des protides sériques</li><li>Hormones thyroïdiennes (TSH ultrasesnsible)</li><li>Carence en vitamines spécifiques (vitamine B9, vitamine B12, vitamine D)</li><li>Sérologie de la maladie cœliaque (anticorps anti-transglutaminase IgA et IgA totaux)</li></ul>"},{"i":"0eb23b50152c","n":285,"o":"285-9","u":"Diagnostic positif","t":"Connaître la stratégie d’exploration d’une diarrhée chronique","q":"Quels examens biologiques de première intention sont à envisager face à une diarrhée chronique ?","a":"<p>Les examens biologiques de première intention comprennent :</p><ul><li>Un <strong>bilan martial</strong> (NFS, ferritinémie, coefficient de saturation de la transferrine).</li><li>Un <strong>bilan inflammatoire</strong> (CRP).</li><li>Un <strong>bilan nutritionnel</strong> (albuminémie, hémoglobine, ionogramme sanguin, créatininémie, bilan hépatique, calcémie, magnésémie, vitamine D).</li><li>Un <strong>dosage des hormones thyroïdiennes</strong> (TSH).</li><li>Un <strong>dosage des auto-anticorps</strong> (Ac anti-transglutaminase, Ac anti-endomysium en cas de suspicion de maladie cœliaque).</li></ul>"},{"i":"1ccc81c44256","n":285,"o":"285-9","u":"Diagnostic positif","t":"Connaître la stratégie d’exploration d’une diarrhée chronique","q":"Comment doit-on définir une diarrhée chronique pour débuter son exploration ?","a":"<p>Une diarrhée est qualifiée de chronique lorsqu'elle dure depuis <strong>plus de 4 semaines</strong> (ou <strong>plus de 1 mois</strong>) et se caractérise par une augmentation de la fréquence des selles (plus de 3 par jour) et/ou une diminution de leur consistance (selles liquides ou molles).</p>"},{"i":"419ee22fd979","n":285,"o":"285-9","u":"Diagnostic positif","t":"Connaître la stratégie d’exploration d’une diarrhée chronique","q":"Quelle est la toute première étape de l'exploration d'une diarrhée chronique ?","a":"<p>La première étape est une <strong>anamnèse rigoureuse</strong> et un <strong>examen clinique complet</strong>, recherchant notamment :</p><ul><li>Les caractéristiques de la diarrhée (liquide, graisseuse, glairosanguinolente etc.).</li><li>Les signes extradigestifs associés (fièvre, arthralgies, lésions cutanées...).</li><li>Les antécédents médicaux et chirurgicaux.</li><li>La prise de médicaments, en particulier ceux nouvellement introduits.</li><li>Les voyages récents ou l'exposition à des toxines.</li><li>Les signes de gravité (altération de l'état général, déshydratation, carences).</li></ul>"},{"i":"839ccf305a7e","n":285,"o":"285-9","u":"Diagnostic positif","t":"Connaître la stratégie d’exploration d’une diarrhée chronique","q":"Quels examens coprologiques sont utiles dans l'exploration initiale d'une diarrhée chronique ?","a":"<p>Les examens coprologiques initiaux à envisager sont :</p><ul><li>Une <strong>coproculture</strong> avec recherche de toxines (<em>Clostridioides difficile</em>).</li><li>Un examen parasitologique des selles (<strong>EPS</strong>) répété sur 3 échantillons.</li><li>Un <strong>dosage de la calprotectine fécale</strong>, marqueur d'inflammation intestinale, pour distinguer les diarrhées organiques des fonctionnelles.</li><li>Recherche de <strong>graisses dans les selles</strong> (stéatorrhée).</li></ul>"},{"i":"90f508ef65e8","n":285,"o":"285-9","u":"Diagnostic positif","t":"Connaître la stratégie d’exploration d’une diarrhée chronique","q":"Quand faut-il envisager une endoscopie digestive haute et basse dans la stratégie d'exploration d'une diarrhée chronique ?","a":"<p>La <strong>coloscopie avec iléoscopie et biopsies étagées</strong> est systématique après le bilan biologique et coprologique initial, surtout si la calprotectine fécale est élevée ou s'il y a des signes d'alarme (saignement, perte de poids, anémie). Une <strong>endoscopie oeso-gastro-duodénale (EOGD) avec biopsies duodénales</strong> est indiquée en cas de suspicion de malabsorption ou de diarrhée liquidienne majeure, ou si les biopsies du côlon sont normales.</p>"}]};